<?php
require_once __DIR__.'/../includes/bootstrap.php';
$done=false;$error='';
if(INSTALL_KEY==='CHANGE-THIS-TO-A-LONG-RANDOM-ONE-TIME-KEY'||strlen(INSTALL_KEY)<24){$error='Edit includes/config.php and set INSTALL_KEY to a random value of at least 24 characters.';}
else{try{$pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, last_login DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_code VARCHAR(24) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, whatsapp VARCHAR(30) NOT NULL, service VARCHAR(80) NOT NULL, budget VARCHAR(60) NULL, deadline DATE NULL, brief TEXT NOT NULL, attachment VARCHAR(80) NULL, status VARCHAR(24) NOT NULL DEFAULT 'pending', admin_note TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_orders_status_created(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0)$done=true;
elseif($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(!hash_equals(INSTALL_KEY,(string)($_POST['install_key']??'')))throw new RuntimeException('The one-time installation key is incorrect.');$user=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9_.-]{3,40}$/',$user))throw new RuntimeException('Username must be 3–40 letters, numbers, dots, dashes or underscores.');if(strlen($pass)<12)throw new RuntimeException('Password must have at least 12 characters.');$q=$pdo->prepare('INSERT INTO admins(username,password_hash,created_at) VALUES(?,?,NOW())');$q->execute([$user,password_hash($pass,PASSWORD_DEFAULT)]);$done=true;}
}catch(Throwable $ex){error_log('HG setup: '.$ex->getMessage());$error='Database setup failed. Check the MySQL settings in includes/config.php and confirm the database exists.';}}
?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>One-time setup — Hammad Graphic</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-body"><main class="admin-login-wrap"><a class="brand" href="../index.php"><span class="brand-mark">H<span>G</span></span><span class="brand-name">HAMMAD<span>GRAPHIC</span></span></a><section class="admin-login-card"><div class="eyebrow">ONE-TIME INSTALLATION</div><h1>Set up your<br><em>admin account.</em></h1><?php if($done): ?><div class="alert alert-success">Setup is complete or an admin account already exists. Delete <strong>admin/setup.php</strong> from your hosting account now.</div><a class="button button-primary" href="login.php">Go to admin login ↗</a><?php else: ?><?php if($error): ?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><p>Configure the database and INSTALL_KEY in includes/config.php first. This installer is for first-time setup only.</p><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>One-time install key<input type="password" name="install_key" required autocomplete="off"></label><label>Admin username<input name="username" minlength="3" maxlength="40" required></label><label>Admin password<input type="password" name="password" minlength="12" required autocomplete="new-password"><small>Use at least 12 characters and keep it private.</small></label><button class="button button-primary">Create admin account</button></form><?php endif; ?></section></main></body></html>